/* ========================================
   CSS Reset & Base Styles
   ======================================== */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    /* Color Palette */
    --primary-color: #6366f1;
    --primary-hover: #4f46e5;
    --secondary-color: #8b5cf6;
    --accent-color: #ec4899;
    --success-color: #10b981;
    --danger-color: #ef4444;
    --warning-color: #f59e0b;

    /* Neutral Colors */
    --bg-color: #0f172a;
    --card-bg: #1e293b;
    --card-hover: #334155;
    --text-primary: #f1f5f9;
    --text-secondary: #cbd5e1;
    --text-muted: #94a3b8;
    --border-color: #334155;

    /* Spacing */
    --spacing-xs: 0.5rem;
    --spacing-sm: 0.75rem;
    --spacing-md: 1rem;
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
    --spacing-2xl: 3rem;

    /* Border Radius */
    --radius-sm: 0.375rem;
    --radius-md: 0.5rem;
    --radius-lg: 0.75rem;
    --radius-xl: 1rem;

    /* Shadows */
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
    --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.1);

    /* Transitions */
    --transition-fast: 150ms ease-in-out;
    --transition-base: 200ms ease-in-out;
    --transition-slow: 300ms ease-in-out;
}

body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
    color: var(--text-primary);
    min-height: 100vh;
    padding: var(--spacing-lg);
    line-height: 1.6;
}

/* ========================================
   Header & Greeting Section
   ======================================== */
header {
    text-align: center;
    padding: var(--spacing-2xl) var(--spacing-lg);
    margin-bottom: var(--spacing-2xl);
    background: var(--card-bg);
    border-radius: var(--radius-xl);
    box-shadow: var(--shadow-lg);
    border: 1px solid var(--border-color);
}

#time-display {
    font-size: 3.5rem;
    font-weight: 700;
    background: linear-gradient(135deg, var(--primary-color), var(--secondary-color));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
    margin-bottom: var(--spacing-sm);
    letter-spacing: 0.05em;
}

#date-display {
    font-size: 1.125rem;
    color: var(--text-secondary);
    margin-bottom: var(--spacing-lg);
    font-weight: 500;
}

#greeting-text {
    font-size: 1.75rem;
    color: var(--text-primary);
    font-weight: 600;
}

/* ========================================
   Main Content Layout
   ======================================== */
main {
    max-width: 900px;
    margin: 0 auto;
}

section {
    background: var(--card-bg);
    padding: var(--spacing-xl);
    margin-bottom: var(--spacing-xl);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow-md);
    border: 1px solid var(--border-color);
    transition: transform var(--transition-base), box-shadow var(--transition-base);
}

section:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
}

section h3 {
    font-size: 1.5rem;
    margin-bottom: var(--spacing-lg);
    color: var(--text-primary);
    font-weight: 600;
    padding-bottom: var(--spacing-sm);
    border-bottom: 2px solid var(--primary-color);
}

section h4 {
    font-size: 1.125rem;
    margin-top: var(--spacing-lg);
    margin-bottom: var(--spacing-md);
    color: var(--text-secondary);
    font-weight: 500;
}

hr {
    display: none;
}

/* ========================================
   Focus Timer Section
   ======================================== */
#timer-display {
    font-size: 4rem;
    font-weight: 700;
    text-align: center;
    color: var(--primary-color);
    margin: var(--spacing-xl) 0;
    font-variant-numeric: tabular-nums;
    letter-spacing: 0.05em;
}

section nav {
    display: flex;
    gap: var(--spacing-md);
    justify-content: center;
    flex-wrap: wrap;
}

/* ========================================
   Button Styles
   ======================================== */
button {
    padding: var(--spacing-sm) var(--spacing-lg);
    font-size: 1rem;
    font-weight: 600;
    border: none;
    border-radius: var(--radius-md);
    cursor: pointer;
    transition: all var(--transition-base);
    box-shadow: var(--shadow-sm);
    font-family: inherit;
}

button:hover {
    transform: translateY(-1px);
    box-shadow: var(--shadow-md);
}

button:active {
    transform: translateY(0);
}

#start-btn {
    background: linear-gradient(135deg, var(--success-color), #059669);
    color: white;
}

#start-btn:hover {
    background: linear-gradient(135deg, #059669, #047857);
}

#stop-btn {
    background: linear-gradient(135deg, var(--danger-color), #dc2626);
    color: white;
}

#stop-btn:hover {
    background: linear-gradient(135deg, #dc2626, #b91c1c);
}

#reset-btn {
    background: linear-gradient(135deg, var(--warning-color), #d97706);
    color: white;
}

#reset-btn:hover {
    background: linear-gradient(135deg, #d97706, #b45309);
}

button[type="submit"],
button[type="add-link"] {
    background: linear-gradient(135deg, var(--primary-color), var(--primary-hover));
    color: white;
}

button[type="submit"]:hover,
button[type="add-link"]:hover {
    background: linear-gradient(135deg, var(--primary-hover), #4338ca);
}

/* ========================================
   Form Styles
   ======================================== */
form {
    display: flex;
    flex-direction: column;
    gap: var(--spacing-md);
    margin-bottom: var(--spacing-lg);
}

label {
    font-weight: 500;
    color: var(--text-secondary);
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

input[type="text"],
input[type="url"] {
    padding: var(--spacing-sm) var(--spacing-md);
    font-size: 1rem;
    border: 2px solid var(--border-color);
    border-radius: var(--radius-md);
    background: var(--bg-color);
    color: var(--text-primary);
    transition: all var(--transition-base);
    font-family: inherit;
}

input[type="text"]:focus,
input[type="url"]:focus {
    outline: none;
    border-color: var(--primary-color);
    box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.1);
}

input[type="text"]::placeholder,
input[type="url"]::placeholder {
    color: var(--text-muted);
}

/* ========================================
   To-Do List Styles
   ======================================== */
#todo-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: var(--spacing-sm);
}

.todo-item {
    display: flex;
    align-items: center;
    gap: var(--spacing-md);
    padding: var(--spacing-md);
    background: var(--bg-color);
    border-radius: var(--radius-md);
    border: 1px solid var(--border-color);
    transition: all var(--transition-base);
}

.todo-item:hover {
    background: var(--card-hover);
    border-color: var(--primary-color);
}

.todo-item.completed {
    opacity: 0.6;
}

.todo-item.completed .todo-text {
    text-decoration: line-through;
    color: var(--text-muted);
}

.todo-checkbox {
    width: 20px;
    height: 20px;
    cursor: pointer;
    accent-color: var(--primary-color);
}

.todo-text {
    flex: 1;
    font-size: 1rem;
    color: var(--text-primary);
    word-break: break-word;
}

.delete-btn {
    padding: var(--spacing-xs) var(--spacing-md);
    background: var(--danger-color);
    color: white;
    font-size: 0.875rem;
    border-radius: var(--radius-sm);
}

.delete-btn:hover {
    background: #dc2626;
}

/* ========================================
   Quick Links Section
   ======================================== */
#links-container {
    display: flex;
    flex-wrap: wrap;
    gap: var(--spacing-md);
}

.link-item {
    display: flex;
    align-items: center;
    gap: var(--spacing-sm);
    background: var(--bg-color);
    padding: var(--spacing-sm) var(--spacing-md);
    border-radius: var(--radius-md);
    border: 1px solid var(--border-color);
    transition: all var(--transition-base);
}

.link-item:hover {
    background: var(--card-hover);
    border-color: var(--primary-color);
}

.link-button {
    text-decoration: none;
    color: var(--primary-color);
    font-weight: 500;
    transition: color var(--transition-fast);
}

.link-button:hover {
    color: var(--secondary-color);
}

.link-delete {
    padding: var(--spacing-xs) var(--spacing-sm);
    background: var(--danger-color);
    color: white;
    font-size: 0.75rem;
    border-radius: var(--radius-sm);
}

.link-delete:hover {
    background: #dc2626;
}

/* ========================================
   Empty State
   ======================================== */
.empty-state {
    text-align: center;
    padding: var(--spacing-xl);
    color: var(--text-muted);
    font-style: italic;
}

/* ========================================
   Responsive Design
   ======================================== */
@media (max-width: 768px) {
    body {
        padding: var(--spacing-md);
    }

    #time-display {
        font-size: 2.5rem;
    }

    #greeting-text {
        font-size: 1.5rem;
    }

    section {
        padding: var(--spacing-lg);
    }

    #timer-display {
        font-size: 3rem;
    }

    section nav {
        flex-direction: column;
    }

    button {
        width: 100%;
    }
}

@media (max-width: 480px) {
    #time-display {
        font-size: 2rem;
    }

    #timer-display {
        font-size: 2.5rem;
    }

    section h3 {
        font-size: 1.25rem;
    }
}

/* ========================================
   Accessibility
   ======================================== */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

button:focus-visible,
input:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 2px;
}

/* ========================================
   To-Do List Life Dashboard - Main Script
   ======================================== */

// ========================================
// 1. REAL-TIME CLOCK & GREETING
// ========================================

function updateTimeAndDate() {
    const now = new Date();

    // Update time display (HH:MM:SS)
    const hours = String(now.getHours()).padStart(2, '0');
    const minutes = String(now.getMinutes()).padStart(2, '0');
    const seconds = String(now.getSeconds()).padStart(2, '0');
    document.getElementById('time-display').textContent = `${hours}:${minutes}:${seconds}`;

    // Update date display
    const options = { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' };
    document.getElementById('date-display').textContent = now.toLocaleDateString('en-US', options);

    // Update greeting based on time
    const hour = now.getHours();
    let greeting = '';
    if (hour >= 5 && hour < 12) {
        greeting = 'Good Morning';
    } else if (hour >= 12 && hour < 17) {
        greeting = 'Good Afternoon';
    } else if (hour >= 17 && hour < 21) {
        greeting = 'Good Evening';
    } else {
        greeting = 'Good Night';
    }

    // Get user name from localStorage or use default
    const userName = localStorage.getItem('userName') || 'Yudha';
    document.getElementById('greeting-text').textContent = `${greeting}, ${userName}`;
}

// Update clock every second
setInterval(updateTimeAndDate, 1000);
updateTimeAndDate(); // Initial call


// ========================================
// 2. FOCUS TIMER (POMODORO STYLE)
// ========================================

let timerInterval = null;
let remainingSeconds = 30 * 60; // Default 30 minutes
let isTimerRunning = false;

// Load timer state from localStorage
function loadTimerState() {
    const savedTime = localStorage.getItem('timerRemainingSeconds');
    if (savedTime) {
        remainingSeconds = parseInt(savedTime, 10);
    }
    updateTimerDisplay();
}

// Save timer state to localStorage
function saveTimerState() {
    localStorage.setItem('timerRemainingSeconds', remainingSeconds);
}

// Update timer display
function updateTimerDisplay() {
    const minutes = Math.floor(remainingSeconds / 60);
    const seconds = remainingSeconds % 60;
    document.getElementById('timer-display').textContent = 
        `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
}

// Start timer
function startTimer() {
    if (isTimerRunning) return;

    isTimerRunning = true;
    timerInterval = setInterval(() => {
        if (remainingSeconds > 0) {
            remainingSeconds--;
            updateTimerDisplay();
            saveTimerState();
        } else {
            stopTimer();
            alert('⏰ Timer finished! Time to take a break!');
        }
    }, 1000);
}

// Stop timer
function stopTimer() {
    isTimerRunning = false;
    if (timerInterval) {
        clearInterval(timerInterval);
        timerInterval = null;
    }
    saveTimerState();
}

// Reset timer
function resetTimer() {
    stopTimer();
    remainingSeconds = 30 * 60; // Reset to 30 minutes
    updateTimerDisplay();
    saveTimerState();
}

// Event listeners for timer buttons
document.getElementById('start-btn').addEventListener('click', startTimer);
document.getElementById('stop-btn').addEventListener('click', stopTimer);
document.getElementById('reset-btn').addEventListener('click', resetTimer);

// Load timer state on page load
loadTimerState();


// ========================================
// 3. TO-DO LIST
// ========================================

let todos = [];

// Load todos from localStorage
function loadTodos() {
    const savedTodos = localStorage.getItem('todos');
    if (savedTodos) {
        todos = JSON.parse(savedTodos);
    }
    renderTodos();
}

// Save todos to localStorage
function saveTodos() {
    localStorage.setItem('todos', JSON.stringify(todos));
}

// Render todos to the DOM
function renderTodos() {
    const todoList = document.getElementById('todo-list');
    todoList.innerHTML = '';

    if (todos.length === 0) {
        todoList.innerHTML = '<li class="empty-state">No tasks yet. Add one above!</li>';
        return;
    }

    todos.forEach((todo, index) => {
        const li = document.createElement('li');
        li.className = `todo-item ${todo.completed ? 'completed' : ''}`;

        // Checkbox
        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.className = 'todo-checkbox';
        checkbox.checked = todo.completed;
        checkbox.addEventListener('change', () => toggleTodo(index));

        // Text
        const span = document.createElement('span');
        span.className = 'todo-text';
        span.textContent = todo.text;

        // Delete button
        const deleteBtn = document.createElement('button');
        deleteBtn.className = 'delete-btn';
        deleteBtn.textContent = 'Delete';
        deleteBtn.addEventListener('click', () => deleteTodo(index));

        li.appendChild(checkbox);
        li.appendChild(span);
        li.appendChild(deleteBtn);
        todoList.appendChild(li);
    });
}

// Add new todo
function addTodo(text) {
    if (text.trim() === '') return;

    todos.push({
        text: text.trim(),
        completed: false,
        id: Date.now()
    });

    saveTodos();
    renderTodos();
}

// Toggle todo completion
function toggleTodo(index) {
    todos[index].completed = !todos[index].completed;
    saveTodos();
    renderTodos();
}

// Delete todo
function deleteTodo(index) {
    if (confirm('Are you sure you want to delete this task?')) {
        todos.splice(index, 1);
        saveTodos();
        renderTodos();
    }
}

// Event listener for todo form
document.getElementById('todo-form').addEventListener('submit', (e) => {
    e.preventDefault();
    const input = document.getElementById('todo-input');
    addTodo(input.value);
    input.value = '';
});

// Load todos on page load
loadTodos();


// ========================================
// 4. QUICK LINKS
// ========================================

let links = [];

// Load links from localStorage
function loadLinks() {
    const savedLinks = localStorage.getItem('quickLinks');
    if (savedLinks) {
        links = JSON.parse(savedLinks);
    }
    renderLinks();
}

// Save links to localStorage
function saveLinks() {
    localStorage.setItem('quickLinks', JSON.stringify(links));
}

// Render links to the DOM
function renderLinks() {
    const linksContainer = document.getElementById('links-container');
    linksContainer.innerHTML = '';

    if (links.length === 0) {
        linksContainer.innerHTML = '<div class="empty-state">No quick links yet. Add one above!</div>';
        return;
    }

    links.forEach((link, index) => {
        const linkItem = document.createElement('div');
        linkItem.className = 'link-item';

        // Link button
        const a = document.createElement('a');
        a.href = link.url;
        a.target = '_blank';
        a.rel = 'noopener noreferrer';
        a.className = 'link-button';
        a.textContent = link.name;

        // Delete button
        const deleteBtn = document.createElement('button');
        deleteBtn.className = 'link-delete';
        deleteBtn.textContent = '×';
        deleteBtn.addEventListener('click', () => deleteLink(index));

        linkItem.appendChild(a);
        linkItem.appendChild(deleteBtn);
        linksContainer.appendChild(linkItem);
    });
}

// Add new link
function addLink(name, url) {
    if (name.trim() === '' || url.trim() === '') return;

    // Basic URL validation
    let validUrl = url.trim();
    if (!validUrl.startsWith('http://') && !validUrl.startsWith('https://')) {
        validUrl = 'https://' + validUrl;
    }

    links.push({
        name: name.trim(),
        url: validUrl,
        id: Date.now()
    });

    saveLinks();
    renderLinks();
}

// Delete link
function deleteLink(index) {
    if (confirm('Are you sure you want to delete this link?')) {
        links.splice(index, 1);
        saveLinks();
        renderLinks();
    }
}

// Event listener for link form
document.getElementById('link-form').addEventListener('submit', (e) => {
    e.preventDefault();
    const nameInput = document.getElementById('link-name');
    const urlInput = document.getElementById('link-url');
    addLink(nameInput.value, urlInput.value);
    nameInput.value = '';
    urlInput.value = '';
});

// Load links on page load
loadLinks();


// ========================================
// 5. KEYBOARD SHORTCUTS (BONUS)
// ========================================

document.addEventListener('keydown', (e) => {
    // Ctrl/Cmd + Enter in todo input to submit
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
        const activeElement = document.activeElement;
        if (activeElement.id === 'todo-input') {
            document.getElementById('todo-form').dispatchEvent(new Event('submit'));
        }
    }
});


// ========================================
// 6. INITIALIZATION MESSAGE
// ========================================

console.log('✨ To-Do List Life Dashboard initialized successfully!');
console.log('💾 All data is stored locally in your browser.');

