args.text:
/* ========================================
   Custom CSS untuk Tailwind Integration
   Modern Dark Mode with Glassmorphism
   ======================================== */

/* Import modern Google Fonts */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&family=Poppins:wght@400;500;600;700;800&display=swap');

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

/* Headings menggunakan Poppins */
h1, h2, h3, h4, h5, h6 {
    font-family: 'Poppins', sans-serif;
}

/* Animated background particles effect */
body::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: 
        radial-gradient(circle at 20% 30%, rgba(139, 92, 246, 0.15) 0%, transparent 50%),
        radial-gradient(circle at 80% 70%, rgba(236, 72, 153, 0.15) 0%, transparent 50%),
        radial-gradient(circle at 50% 50%, rgba(6, 182, 212, 0.1) 0%, transparent 50%);
    pointer-events: none;
    z-index: 0;
    animation: float 20s ease-in-out infinite;
}

@keyframes float {
    0%, 100% {
        transform: translateY(0px);
    }
    50% {
        transform: translateY(-20px);
    }
}

/* Ensure content is above background effects */
header, main {
    position: relative;
    z-index: 1;
}

/* Custom animated gradient for timer display */
#timer-display {
    animation: pulse 3s ease-in-out infinite;
}

@keyframes pulse {
    0%, 100% {
        filter: drop-shadow(0 0 20px rgba(167, 139, 250, 0.6));
    }
    50% {
        filter: drop-shadow(0 0 30px rgba(236, 72, 153, 0.7));
    }
}

/* Custom animated gradient for time display */
#time-display {
    animation: glow 4s ease-in-out infinite;
}

@keyframes glow {
    0%, 100% {
        filter: drop-shadow(0 0 30px rgba(167, 139, 250, 0.5));
    }
    50% {
        filter: drop-shadow(0 0 50px rgba(236, 72, 153, 0.6));
    }
}

/* Selection styling */
::selection {
    background: #8b5cf6;
    color: white;
}

::-moz-selection {
    background: #8b5cf6;
    color: white;
}

/* Accessibility */
@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }
}

/* Focus visible untuk accessibility */
button:focus-visible,
input:focus-visible {
    outline: 3px solid #8b5cf6;
    outline-offset: 3px;
}

